// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around TallyLaunchBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// TallyLaunchEntityI.
func (c *TallyLaunchColumns) Marshal(w io.Writer) (err error) {
	ent := tallyLaunchPool.Get().(*cbdml.InEntityFacts)
	defer tallyLaunchPool.Put(ent)
	ent.SetActiveSections(TallyLaunchActiveSections)
	ent.Builder().SetActiveFields(TallyLaunchActiveFields())
	err = TallyLaunchBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("launchcfg: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("launchcfg: marshal write: %w", err)
	}
	return
}

// --- Read path (ra-based). ---

// tallyLaunchReader composes the readaccess helpers this kind needs.
// Constructed per Unmarshal call; released via defer.
type tallyLaunchReader struct {
	EntityId        *ra.ReadAccessFactsPlainEntityIdAttributes
	EntityTimestamp *ra.ReadAccessFactsPlainEntityTimestampAttributes
	TextArray       *ra.ReadAccessFactsTaggedTextArray
	Bool            *ra.ReadAccessFactsTaggedBool
	Symbol          *ra.ReadAccessFactsTaggedSymbol
}

func newTallyLaunchReader() *tallyLaunchReader {
	return &tallyLaunchReader{
		EntityId:        ra.NewReadAccessFactsPlainEntityIdAttributes(),
		EntityTimestamp: ra.NewReadAccessFactsPlainEntityTimestampAttributes(),
		TextArray:       ra.NewReadAccessFactsTaggedTextArray(),
		Bool:            ra.NewReadAccessFactsTaggedBool(),
		Symbol:          ra.NewReadAccessFactsTaggedSymbol(),
	}
}

func (r *tallyLaunchReader) loadFromRecord(rec arrow.Record) (err error) {
	err = r.EntityId.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: load EntityId: %w", err)
		return
	}
	err = r.EntityTimestamp.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: load EntityTimestamp: %w", err)
		return
	}
	err = r.TextArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: load TextArray: %w", err)
		return
	}
	err = r.Bool.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: load Bool: %w", err)
		return
	}
	err = r.Symbol.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: load Symbol: %w", err)
		return
	}
	return
}

func (r *tallyLaunchReader) release() {
	if r == nil {
		return
	}
	if r.EntityId != nil {
		r.EntityId.Release()
	}
	if r.EntityTimestamp != nil {
		r.EntityTimestamp.Release()
	}
	if r.TextArray != nil {
		r.TextArray.Release()
	}
	if r.Bool != nil {
		r.Bool.Release()
	}
	if r.Symbol != nil {
		r.Symbol.Release()
	}
}

// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around TallyLaunchFillFromArrow — the per-row decode lives there.
func (c *TallyLaunchColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newTallyLaunchReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = TallyLaunchFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.TextArray.Attributes, r.TextArray.Memberships,
		r.Bool.Attributes, r.Bool.Memberships,
		r.Symbol.Attributes, r.Symbol.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// TallyLaunchCodec is the buscodec.CodecI bridge for TallyLaunch. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type TallyLaunchCodec struct{}

var _ buscodec.CodecI = (*TallyLaunchCodec)(nil)

// tallyLaunchBusCodec is the package-local singleton wired into buscodec.
var tallyLaunchBusCodec = &TallyLaunchCodec{}

func (inst *TallyLaunchCodec) Name() (n string) {
	n = "tallyLaunch-sparse-cbor"
	return
}

func (inst *TallyLaunchCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=tallyLaunch"
	return
}

func (inst *TallyLaunchCodec) Encode(v any) (b []byte, err error) {
	var row TallyLaunch
	switch x := v.(type) {
	case TallyLaunch:
		row = x
	case *TallyLaunch:
		if x == nil {
			err = eh.Errorf("launchcfg: Encode nil *TallyLaunch")
			return
		}
		row = *x
	default:
		err = eh.Errorf("launchcfg: Encode requires TallyLaunch or *TallyLaunch, got %T", v)
		return
	}
	cols := &TallyLaunchColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("launchcfg: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *TallyLaunchCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*TallyLaunch)
	if !ok {
		err = eh.Errorf("launchcfg: Decode requires *TallyLaunch, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("launchcfg: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &TallyLaunchColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("launchcfg: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("launchcfg: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
